@Override
	public Object getEntity(String entityName, Serializable id) throws CallbackException
	{
		for (Interceptor interceptor : interceptors)
		{
			Object tmp = interceptor.getEntity(entityName, id);
			if (tmp != null)
			{
				return tmp;
			}
		}
		return null;
	}
